// Our own device drawings: a phone and a laptop, flat, in their own units. One light for everything: a soft key from the
// top left, so edges catch light on the top and left, the glass has a diagonal sheen and shadows fall down and right.
// Nothing here is a real product: no logos, no notch shapes copied from a brand, no wordmarks.

import React from 'react';
import { Layer, Rect, Path, Ellipse, linearGradient, radialGradient } from '@kinetographdev/core';
import { clipRR, rr } from './lib.js';

// ---- phone -----------------------------------------------------------------------------------------------------

export const PW = 390;
export const PH = 800;
const BEZEL = 11;
export const SW = PW - 2 * BEZEL; // 368
export const SH = PH - 2 * BEZEL; // 778
export const SR = 46;

export interface PhoneProps {
  id: string;
  /** The screen content, drawn in a 368 x 778 box. */
  children?: React.ReactNode;
  /** Frame colour. */
  frame?: string;
  /** 0..1: how strongly the glass sheen shows. Slide it with `sheenAt` as the phone turns. */
  sheen?: number;
  /** -1..1: where the sheen band sits across the glass. */
  sheenAt?: number;
  /** The home bar colour: light on dark screens, dark on light. */
  bar?: string;
  /** Dim the screen (a phone not yet woken). 0..1. */
  dim?: number;
}

/** A phone at its resting size, top left at the origin. */
export const Phone: React.FC<PhoneProps> = ({ id, children, frame = '#26272b', sheen = 1, sheenAt = 0, bar = '#ffffff', dim = 0 }) => (
  <Layer id={id}>
    {/* side keys, behind the body so only the edge shows */}
    <Rect id={`${id}-k1`} x={-3} y={170} width={5} height={52} radius={2} fill={frame} />
    <Rect id={`${id}-k2`} x={-3} y={240} width={5} height={52} radius={2} fill={frame} />
    <Rect id={`${id}-k3`} x={PW - 2} y={226} width={5} height={84} radius={2} fill={frame} />
    {/* body: the frame colour with a diagonal light and a hairline highlight */}
    <Rect id={`${id}-body`} width={PW} height={PH} radius={58} fill={frame} />
    <Rect
      id={`${id}-light`}
      width={PW}
      height={PH}
      radius={58}
      fill={linearGradient([[0, '#ffffff55'], [0.28, '#ffffff10'], [0.6, '#00000000'], [1, '#00000066']], { angle: 135 })}
    />
    <Rect id={`${id}-edge`} width={PW} height={PH} radius={58} stroke={{ color: '#ffffff30', width: 1.5 }} />
    {/* black glass bezel and the screen */}
    <Rect id={`${id}-bezel`} x={6} y={6} width={PW - 12} height={PH - 12} radius={53} fill="#050506" />
    <Layer id={`${id}-screen`} x={BEZEL} y={BEZEL} clip={clipRR(SW, SH, SR)}>
      <Rect id={`${id}-screenbase`} width={SW} height={SH} fill="#000" />
      {children}
      {dim > 0 ? <Rect id={`${id}-dim`} width={SW} height={SH} fill="#000" opacity={dim} /> : null}
      <Rect
        id={`${id}-sheen`}
        x={-SW * 0.2 + sheenAt * SW * 0.5}
        y={-SH * 0.1}
        width={SW * 0.9}
        height={SH * 1.2}
        rotation={14}
        opacity={0.1 * sheen}
        fill={linearGradient([[0, '#ffffff00'], [0.5, '#ffffff'], [1, '#ffffff00']], { angle: 90 })}
      />
      <Rect id={`${id}-bar`} x={(SW - 124) / 2} y={SH - 16} width={124} height={5} radius={2.5} fill={bar} opacity={0.85} />
    </Layer>
    <Rect id={`${id}-island`} x={(PW - 112) / 2} y={24} width={112} height={32} radius={16} fill="#000" />
    <Ellipse id={`${id}-lens`} x={(PW + 112) / 2 - 26} y={33} width={14} height={14} fill={radialGradient(['#27304a', '#0b0c12'])} />
  </Layer>
);

// ---- laptop ----------------------------------------------------------------------------------------------------

export const LW = 1120;
export const LH = 700; // lid height
export const LBEZEL = 14;
export const LSW = LW - 2 * LBEZEL; // 1092
export const LSH = LH - 2 * LBEZEL - 4; // screen area height
export const BASE_D = 700; // base depth

export interface LidProps {
  id: string;
  children?: React.ReactNode;
  /** The lid's outer colour. */
  shell?: string;
  /** which face to draw: the screen (inside) or the cover (outside) */
  face: 'screen' | 'cover';
}

/** The lid, drawn flat: top left at the origin. The screen face is LW x LH; the cover is the same box mirrored by the caller. */
export const Lid: React.FC<LidProps> = ({ id, children, shell = '#c9ccd2', face }) =>
  face === 'cover' ? (
    <Layer id={id}>
      <Rect id={`${id}-shell`} width={LW} height={LH} radius={26} fill={linearGradient([shell, '#9fa3ab'], { angle: 160 })} />
      <Rect id={`${id}-spec`} width={LW} height={LH} radius={26} fill={linearGradient([[0, '#ffffff66'], [0.4, '#ffffff00'], [1, '#00000033']], { angle: 135 })} />
      {/* a small centred mark: a plain circle, ours */}
      <Ellipse id={`${id}-mark`} x={LW / 2 - 26} y={LH / 2 - 26} width={52} height={52} stroke={{ color: '#ffffff80', width: 3 }} />
    </Layer>
  ) : (
    <Layer id={id}>
      <Rect id={`${id}-shell`} width={LW} height={LH} radius={26} fill={linearGradient([shell, '#8b8f97'], { angle: 160 })} />
      <Rect id={`${id}-edge`} width={LW} height={LH} radius={26} stroke={{ color: '#ffffff40', width: 1.5 }} />
      <Rect id={`${id}-bezel`} x={7} y={7} width={LW - 14} height={LH - 14} radius={20} fill="#050506" />
      <Layer id={`${id}-screen`} x={LBEZEL} y={LBEZEL + 2} clip={clipRR(LSW, LSH, 8)}>
        <Rect id={`${id}-screenbase`} width={LSW} height={LSH} fill="#000" />
        {children}
        <Rect
          id={`${id}-sheen`}
          x={LSW * 0.1}
          y={-LSH * 0.2}
          width={LSW * 0.5}
          height={LSH * 1.5}
          rotation={20}
          opacity={0.07}
          fill={linearGradient([[0, '#ffffff00'], [0.5, '#ffffff'], [1, '#ffffff00']], { angle: 90 })}
        />
      </Layer>
      <Ellipse id={`${id}-cam`} x={LW / 2 - 3} y={5} width={6} height={6} fill="#14161c" />
    </Layer>
  );

/** The base seen from above, drawn flat: LW wide, BASE_D deep, back edge at the top. Keyboard, trackpad, a light falloff. */
export const Base: React.FC<{ id: string; shell?: string }> = ({ id, shell = '#c9ccd2' }) => {
  const keys: React.ReactNode[] = [];
  const rows = 5;
  const kw = 62;
  const gap = 10;
  const cols = 14;
  const x0 = (LW - (cols * kw + (cols - 1) * gap)) / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      keys.push(<Rect key={`${r}-${c}`} id={`${id}-key-${r}-${c}`} x={x0 + c * (kw + gap)} y={70 + r * (kw * 0.86 + gap)} width={kw} height={kw * 0.86} radius={9} fill="#1c1d22" />);
    }
  }
  return (
    <Layer id={id}>
      <Rect id={`${id}-deck`} width={LW} height={BASE_D} radius={30} fill={linearGradient([shell, '#aeb2ba'], { angle: 180 })} />
      <Rect id={`${id}-well`} x={x0 - 22} y={46} width={cols * kw + (cols - 1) * gap + 44} height={rows * (kw * 0.86 + gap) + 40} radius={16} fill="#101115" />
      {keys}
      <Rect id={`${id}-pad`} x={LW / 2 - 200} y={BASE_D - 215} width={400} height={170} radius={14} fill="#00000014" stroke={{ color: '#00000026', width: 2 }} />
      <Rect id={`${id}-fall`} width={LW} height={BASE_D} radius={30} fill={linearGradient([[0, '#00000040'], [0.18, '#00000000'], [0.8, '#ffffff00'], [1, '#ffffff40']], { angle: 180 })} />
      <Rect id={`${id}-dent`} x={LW / 2 - 90} y={BASE_D - 14} width={180} height={14} radius={7} fill="#00000022" />
    </Layer>
  );
};

export { rr };

// Small timing and drawing helpers shared by the showcase components. Every function is pure in the frame number.

import { Easing, interpolate } from 'remotion';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

/** slow in, slow out: the default for anything that travels */
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
/** fast start, long settle: things arriving */
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
/** slow start, fast end: things leaving at speed */
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);

/** from `from` at frame a to `to` at frame b, held outside */
export const ramp = (f: number, a: number, b: number, from: number, to: number, easing: (t: number) => number = ease) =>
  interpolate(f, [a, b], [from, to], { ...clamp, easing });

/** 0 to 1 over [a, b], eased */
export const prog = (f: number, a: number, b: number, easing: (t: number) => number = ease) => ramp(f, a, b, 0, 1, easing);

/** Keyframes [[frame, value], ...] with one easing on every segment. */
export function keys(f: number, k: [number, number][], easing: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * easing((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

/** A damped spring from 0 at frame `a` to 1: overshoots, then settles. `bounce` 0.2 is gentle, 0.5 lively. */
export function spring(f: number, a: number, dur = 30, bounce = 0.25): number {
  const t = (f - a) / dur;
  if (t <= 0) return 0;
  if (t >= 1.6) return 1;
  const damp = 5.5;
  const w = Math.PI * 2 * (0.6 + bounce * 1.4);
  return 1 - Math.exp(-damp * t) * Math.cos(w * t);
}

/** Path data for a w x h rounded rectangle at the origin. */
export const rr = (w: number, h: number, r: number): string => {
  r = Math.min(r, w / 2, h / 2);
  return `M${r} 0H${w - r}A${r} ${r} 0 0 1 ${w} ${r}V${h - r}A${r} ${r} 0 0 1 ${w - r} ${h}H${r}A${r} ${r} 0 0 1 0 ${h - r}V${r}A${r} ${r} 0 0 1 ${r} 0Z`;
};

export const clipRR = (w: number, h: number, r: number) => ({ kind: 'path' as const, d: rr(w, h, r) });

/** Registers a Google Fonts family and returns the name to put in `font`. */
export const useFamily = (family: string, weights: string[] = ['400', '500', '600'], italic = false): string => {
  const mod = makeGoogleFont(family.replace(/\s+/g, ''));
  if (italic) mod.loadFont('italic', { weights });
  return mod.loadFont('normal', { weights }).fontFamily;
};

/** A point on a circle, for arcs: angle in degrees from straight up, clockwise. */
export const onArc = (cx: number, cy: number, r: number, deg: number) => ({
  x: cx + r * Math.sin((deg * Math.PI) / 180),
  y: cy - r * Math.cos((deg * Math.PI) / 180),
});

/** A smooth hash noise in [-1, 1] of a time and a seed: slow handheld drift without Math.random. */
export const drift = (f: number, seed: number, speed = 0.02): number => {
  const t = f * speed;
  const i = Math.floor(t);
  const h = (n: number) => {
    const s = Math.sin((n + seed * 97.13) * 127.1) * 43758.5453;
    return (s - Math.floor(s)) * 2 - 1;
  };
  const u = t - i;
  const s = u * u * (3 - 2 * u);
  return h(i) * (1 - s) + h(i + 1) * s;
};

// Drawn sample screens for the phones: a made-up fitness app called "Stride" (no brand, no real product). Each is drawn in
// the phone's 368 x 778 screen box. `t` (0..1) is the screen's own reveal: the ring sweeps, the bars fill, the line draws.

import React from 'react';
import { Ellipse, Image, Layer, Path, Rect, Text, linearGradient, radialGradient, staticFile } from '@kinetographdev/core';
import type { Stroke } from '@kinetographdev/core';
import { SH, SW } from './devices.js';
import { clamp, ease, prog } from './lib.js';

export const BUILT_IN = ['hero', 'dashboard', 'chart', 'plan'] as const;
export type BuiltIn = (typeof BUILT_IN)[number];

export interface ScreenStyle {
  /** UI font family (already registered). */
  font: string;
  /** The app's accent: a fresh lime by default. */
  accent: string;
  /** Dark ink for light screens and button type. */
  ink: string;
  /** The sage ground of the hero screen. */
  sage: string;
}

export const defaultStyle = (font: string): ScreenStyle => ({ font, accent: '#d9f26b', ink: '#18191b', sage: '#cdd8a4' });

/** Stroke with round caps: the engine draws cap and join though the type does not list them. */
const line = (color: string, width: number, extra: Record<string, unknown> = {}): Stroke =>
  ({ color, width, cap: 'round', join: 'round', ...extra }) as unknown as Stroke;

const StatusBar: React.FC<{ id: string; color: string; font: string }> = ({ id, color, font }) => (
  <Layer id={id}>
    <Text id={`${id}-t`} font={font} weight={600} size={15} color={color} x={34} y={22} lineHeight={1}>
      9:30
    </Text>
    {[0, 1, 2, 3].map((i) => (
      <Rect key={i} id={`${id}-s${i}`} x={284 + i * 4.4} y={34 - i * 2 - 4} width={2.8} height={4 + i * 2} radius={1} fill={color} />
    ))}
    <Rect id={`${id}-b`} x={313} y={25} width={22} height={11} radius={3.5} stroke={{ color, width: 1.2 }} opacity={0.9} />
    <Rect id={`${id}-bf`} x={315} y={27} width={14} height={7} radius={2} fill={color} />
  </Layer>
);

/** a point on a circle for arc paths, 0 deg = up, clockwise */
const pt = (cx: number, cy: number, r: number, deg: number) => {
  const a = ((deg - 90) * Math.PI) / 180;
  return `${(cx + r * Math.cos(a)).toFixed(2)} ${(cy + r * Math.sin(a)).toFixed(2)}`;
};
const arc = (cx: number, cy: number, r: number, from: number, to: number) =>
  `M${pt(cx, cy, r, from)}A${r} ${r} 0 ${to - from > 180 ? 1 : 0} 1 ${pt(cx, cy, r, to)}`;

// ---- 1. hero ---------------------------------------------------------------------------------------------------

const Runner: React.FC<{ id: string; color: string; t: number }> = ({ id, color, t }) => {
  // a stick figure mid-stride, a little hop on the reveal
  const s = line(color, 5);
  return (
    <Layer id={id} x={150} y={150 + (1 - ease(t)) * 14} opacity={ease(t)}>
      <Ellipse id={`${id}-head`} x={52} y={0} width={30} height={32} fill={color} />
      <Path id={`${id}-torso`} d="M66 36 L56 112" stroke={s} />
      <Path id={`${id}-arm1`} d="M64 50 L92 78 L120 66" stroke={s} />
      <Path id={`${id}-arm2`} d="M63 52 L38 80 L14 62" stroke={s} />
      <Path id={`${id}-leg1`} d="M56 112 L92 146 L84 196" stroke={s} />
      <Path id={`${id}-leg2`} d="M56 112 L24 150 L-12 148" stroke={s} />
      <Rect id={`${id}-ground`} x={-60} y={204} width={220} height={3} radius={1.5} fill={color} opacity={0.25} />
    </Layer>
  );
};

const Hero: React.FC<{ id: string; st: ScreenStyle; t: number }> = ({ id, st, t }) => (
  <Layer id={id}>
    <Rect id={`${id}-bg`} width={SW} height={SH} fill={linearGradient([st.sage, '#bdca8f'], { angle: 165 })} />
    <Ellipse id={`${id}-glow`} x={-60} y={-80} width={340} height={340} fill={radialGradient(['#ffffff66', '#ffffff00'])} />
    <StatusBar id={`${id}-sb`} color={st.ink} font={st.font} />
    <Runner id={`${id}-run`} color="#5a6340" t={t} />
    <Text id={`${id}-h`} font={st.font} weight={600} size={42} color={st.ink} x={32} y={SH - 300} lineHeight={1.02} maxWidth={300} opacity={prog(t, 0.2, 0.7)}>
      Unleash full potential
    </Text>
    <Text id={`${id}-p`} font={st.font} weight={400} size={15} color="#3d4430" x={32} y={SH - 200} lineHeight={1.35} maxWidth={260} opacity={prog(t, 0.3, 0.8)}>
      Plans that move with you, one run at a time.
    </Text>
    <Rect id={`${id}-btn`} x={32} y={SH - 130} width={150} height={48} radius={24} fill={st.ink} opacity={prog(t, 0.4, 0.9)} />
    <Text id={`${id}-bt`} font={st.font} weight={600} size={14} color={st.accent} x={32 + 38} y={SH - 130 + 17} lineHeight={1} opacity={prog(t, 0.4, 0.9)}>
      Start now
    </Text>
  </Layer>
);

// ---- 2. dashboard ----------------------------------------------------------------------------------------------

const Dashboard: React.FC<{ id: string; st: ScreenStyle; t: number }> = ({ id, st, t }) => {
  const sweep = ease(prog(t, 0.1, 0.8));
  const rows: [string, string, number][] = [
    ['Running', '5.2 km today', 0.78],
    ['Cycling', '12 km this week', 0.5],
    ['Strength', '2 sessions', 0.62],
  ];
  return (
    <Layer id={id}>
      <Rect id={`${id}-bg`} width={SW} height={SH} fill="#17181a" />
      <StatusBar id={`${id}-sb`} color="#ffffff" font={st.font} />
      <Ellipse id={`${id}-av`} x={28} y={70} width={32} height={32} fill={st.accent} />
      <Text id={`${id}-avt`} font={st.font} weight={600} size={12} color={st.ink} x={36} y={80} lineHeight={1}>
        AL
      </Text>
      <Text id={`${id}-nm`} font={st.font} weight={600} size={14} color="#fff" x={70} y={72} lineHeight={1}>
        Alex Lind
      </Text>
      <Text id={`${id}-pm`} font={st.font} weight={400} size={11} color="#8d9096" x={70} y={91} lineHeight={1}>
        Premium member
      </Text>
      <Rect id={`${id}-card`} x={20} y={128} width={SW - 40} height={236} radius={22} fill="#232427" />
      <Text id={`${id}-wg`} font={st.font} weight={500} size={13} color="#a3a6ab" x={38} y={146} lineHeight={1}>
        Weekly goal
      </Text>
      <Layer id={`${id}-ring`} x={SW / 2} y={236}>
        <Path id={`${id}-ring-bg`} d={arc(0, 0, 62, 0, 359.9)} stroke={line('#3a3c40', 12)} />
        <Path id={`${id}-ring-fg`} d={arc(0, 0, 62, 0, Math.max(0.5, 240 * sweep))} stroke={line(st.accent, 12)} />
        <Text id={`${id}-ring-n`} font={st.font} weight={600} size={38} color="#fff" x={-26} y={-22} lineHeight={1}>
          {sweep > 0.6 ? '2' : '1'}
        </Text>
        <Text id={`${id}-ring-m`} font={st.font} weight={400} size={20} color="#8d9096" x={2} y={-12} lineHeight={1}>
          / 3
        </Text>
      </Layer>
      {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((d, i) => {
        const on = i < 2;
        const x = 38 + i * 44;
        return (
          <Layer key={i} id={`${id}-d${i}`}>
            <Ellipse id={`${id}-d${i}-c`} x={x} y={326} width={26} height={26} fill={on ? st.accent : '#2f3033'} />
            <Text id={`${id}-d${i}-t`} font={st.font} weight={600} size={11} color={on ? st.ink : '#7d8086'} x={x + 8.5} y={334} lineHeight={1}>
              {d}
            </Text>
          </Layer>
        );
      })}
      <Text id={`${id}-yp`} font={st.font} weight={600} size={15} color="#fff" x={26} y={392} lineHeight={1}>
        Your progress
      </Text>
      <Text id={`${id}-see`} font={st.font} weight={500} size={12} color={st.accent} x={SW - 70} y={394} lineHeight={1}>
        See all
      </Text>
      {rows.map(([n, sub, v], i) => {
        const y = 428 + i * 74;
        const k = ease(prog(t, 0.35 + i * 0.1, 0.9));
        return (
          <Layer key={n} id={`${id}-r${i}`} y={y} opacity={prog(t, 0.3 + i * 0.1, 0.6 + i * 0.1)}>
            <Rect id={`${id}-r${i}-bg`} x={20} width={SW - 40} height={62} radius={18} fill="#202124" />
            <Rect id={`${id}-r${i}-ic`} x={32} y={15} width={32} height={32} radius={10} fill="#2f3033" />
            <Ellipse id={`${id}-r${i}-dot`} x={42} y={25} width={12} height={12} fill={st.accent} />
            <Text id={`${id}-r${i}-n`} font={st.font} weight={600} size={13} color="#fff" x={76} y={14} lineHeight={1}>
              {n}
            </Text>
            <Text id={`${id}-r${i}-s`} font={st.font} weight={400} size={11} color="#8d9096" x={76} y={33} lineHeight={1}>
              {sub}
            </Text>
            <Rect id={`${id}-r${i}-tr`} x={196} y={28} width={128} height={6} radius={3} fill="#34363a" />
            <Rect id={`${id}-r${i}-fl`} x={196} y={28} width={Math.max(6, 128 * v * k)} height={6} radius={3} fill={st.accent} />
          </Layer>
        );
      })}
    </Layer>
  );
};

// ---- 3. chart --------------------------------------------------------------------------------------------------

const Chart: React.FC<{ id: string; st: ScreenStyle; t: number }> = ({ id, st, t }) => {
  const pts: [number, number][] = [0, 1, 2, 3, 4, 5, 6, 7].map((i) => [
    24 + i * 46,
    430 - 70 * (0.55 + 0.35 * Math.sin(i * 0.9 + 0.4) + 0.2 * Math.sin(i * 2.1)) - i * 8,
  ]);
  let d = `M${pts[0][0]} ${pts[0][1]}`;
  for (let i = 1; i < pts.length; i++) {
    const [x0, y0] = pts[i - 1];
    const [x1, y1] = pts[i];
    const mx = (x0 + x1) / 2;
    d += ` C${mx} ${y0} ${mx} ${y1} ${x1} ${y1}`;
  }
  const area = `${d} L${pts[7][0]} 520 L${pts[0][0]} 520Z`;
  const reveal = ease(prog(t, 0.15, 0.85));
  const kcal = Math.round(740 * ease(prog(t, 0.05, 0.7)));
  return (
    <Layer id={id}>
      <Rect id={`${id}-bg`} width={SW} height={SH} fill="#f3f3ee" />
      <StatusBar id={`${id}-sb`} color={st.ink} font={st.font} />
      <Text id={`${id}-l`} font={st.font} weight={400} size={13} color="#7b7d78" x={28} y={86} lineHeight={1}>
        Burned calories
      </Text>
      <Text id={`${id}-n`} font={st.font} weight={600} size={58} color={st.ink} x={26} y={110} lineHeight={1}>
        {String(kcal)}
      </Text>
